function normalizeEditablePromptInput(input) {
  const request = input === undefined ? {} : input;
  return Object.freeze({
    subject: request.subject,
    predicate: request.predicate,
    record: supplied(request, "record", {}),
    typedRecord: supplied(request, "typedRecord", {}),
    currentContext: supplied(request, "currentContext", POLICY.missingCurrentContext),
    mode: supplied(request, "mode", POLICY.missingMode),
    choiceDetailsProviders: supplied(request, "choiceDetailsProviders", EMPTY_LIST),
    contractPolicyProviders: supplied(request, "contractPolicyProviders", EMPTY_LIST),
    profiler: supplied(request, "profiler", POLICY.missingProfiler),
  });
}

function requiresStrictChoiceValidation(contract) {
  return contract.iface?.type === POLICY.adapterInterface && contract.slot?.predicate === POLICY.adapterPredicate;
}

function contractChoiceDetails(contract, context) {
  const slot = Object(contract.slot);
  const addingMany = context.mode === "add" && slotIsMany(slot);
  const existing = addingMany ? new Set(existingContractValues(contract)) : null;
  const provided = providerChoiceDetails(contract, context);
  if (provided !== null) return provided;
  if (Array.isArray(slot.allowed) && slot.allowed.length) return enumerationChoiceDetails(slot.allowed, existing);
  const adapter = adapterTransformChoiceDetails(contract, context);
  if (adapter !== null) return adapter;
  if (slot.valueType !== "ref") return [];
  const policy = applyContractPolicy(contract, context);
  const compatibleType = [contract.compatibleRefType, policy.compatibleRefType, ""].find(Boolean);
  return referenceChoiceDetails(context, compatibleType, existing);
}

function validateChoiceValue(contract, value, context, helpers) {
  const slot = Object(contract.slot);
  if (slot.valueType === "ref" && !requiresStrictChoiceValidation(contract)) return;
  const choices = contractChoiceDetails(contract, context);
  if (!choices.length) return;
  const match = choices.find(choice => choice.value === value);
  const subject = text(contract.subject, "<unknown>");
  const predicate = text(slot.predicate, "");
  if (match === undefined) helpers.failSemantic(helpers.mutationIssue(
    "invalid-mutation-value", `Mutation value for ${subject}.${predicate} failed allowed-value validation.`,
    { subject: text(contract.subject, ""), predicate, value, allowed: choices.filter(choice => !choice.disabled).map(choice => choice.value) },
  ), { statusCode: 400 });
  if (match.disabled) {
    const reason = text(match.reason, "disabled choice");
    helpers.failSemantic(helpers.mutationIssue(
      "invalid-mutation-value", `Mutation value for ${subject}.${predicate} is unavailable: ${reason}.`,
      { subject: text(contract.subject, ""), predicate, value, reason },
    ), { statusCode: 400 });
  }
}

function preferredSiblingText(projectedValue, currentValue) {
  if (projectedValue) return String(projectedValue);
  if (currentValue) return String(currentValue);
  return POLICY.missingSiblingValue;
}

function assignmentParentSubjects(prog, assignmentSubject) {
  return asStore(prog).factsForObject(assignmentSubject)
    .filter(fact => fact.p === POLICY.assignmentParentPredicate && fact.pol !== "is-not")
    .map(fact => fact.s);
}

function assignmentSiblingValue(prog, projection, parentSubject, predicate) {
  for (const assignmentSubject of asStore(prog).objects(parentSubject, POLICY.assignmentParentPredicate)) {
    const projectedAssignment = projection?.[assignmentSubject];
    const currentPredicate = latestResolutionText(prog, assignmentSubject, POLICY.assignmentNamePredicate);
    const assignmentPredicate = preferredSiblingText(projectedAssignment?.predicate, currentPredicate).trim();
    if (assignmentPredicate !== predicate) continue;
    const currentValue = latestResolutionText(prog, assignmentSubject, POLICY.assignmentValuePredicate);
    return preferredSiblingText(projectedAssignment?.value, currentValue);
  }
  return POLICY.missingSiblingValue;
}

function activeSubjectBindings(prog, contextSubject, subject) {
  return contextBindings(prog, contextSubject).filter(binding => binding.memberSubject === subject);
}

function activeSubjectReferences(prog, contextSubject, subject) {
  return contextReferenceBindings(prog, contextSubject).filter(reference => reference.targetSubject === subject);
}

function explicitBindingForMutation(combinedFacts, contextSubject, subject) {
  const binding = activeSubjectBindings(combinedFacts, contextSubject, subject)[0];
  return binding ? binding : null;
}

function explicitReferenceForMutation(combinedFacts, contextSubject, subject, referenceSubject) {
  const references = activeSubjectReferences(combinedFacts, contextSubject, subject);
  const selection = referenceSubject === undefined ? POLICY.missingReference : referenceSubject;
  if (selection) {
    const reference = references.find(candidate => candidate.subject === selection);
    return reference ? reference : null;
  }
  return references.length === 1 ? references[0] : null;
}

function classifyContextMutationOperation(operation) {
  return POLICY.operationRoutes.get(operation);
}

function resolveKnownMutationContext(prog, contextSubject, contextSpecs, helpers) {
  const context = contextSpecs(prog).find(entry => entry.subject === contextSubject);
  if (!context) {
    helpers.fail(helpers.issue(
      POLICY.unknownContextDiagnostic,
      `Unknown context: ${contextSubject}.`,
      { context: contextSubject },
    ), { statusCode: POLICY.unknownContextStatus });
  }
  return context;
}

function prepareContextMutation(input, helpers) {
  const { semantic, actor, subject, record, mutation } = input;
  const operation = mutation.operation;
  const kind = classifyContextMutationOperation(operation);
  if (!kind) {
    helpers.fail(helpers.issue(
      POLICY.unknownOperationDiagnostic,
      `Unknown mutation operation: ${operation}.`,
      { operation },
    ), { statusCode: POLICY.unknownOperationStatus });
  }
  const context = mutation.context === undefined ? POLICY.missingContext : mutation.context;
  helpers.ensureKnownContext(semantic, context);
  const scope = helpers.authorityScopeForOperation(semantic, actor, operation, { context, subject, record });
  if (!scope.allowed) {
    helpers.fail(helpers.issue(
      POLICY.deniedDiagnostic,
      `Actor ${actor} lacks ${operation} authority for ${subject} in ${context}.`,
      { actor, subject, context, operation, requiredAuthority: scope.authority, grant: scope.grant },
    ), { statusCode: POLICY.deniedStatus });
  }
  return Object.freeze({ context, scope, kind });
}

function removableValueAction(subject, slot, values, projection, policyFacts) {
  if (!values.length) return null;
  if (slot.cardinality === POLICY.singleCardinality) return null;
  if (slot.cardinality === POLICY.minimumOneCardinality && values.length <= 1) return null;
  const reference = slot.valueType === POLICY.referenceValueType;
  if (values.length === 1) return singleRemovalAction(subject, slot, values[0], reference, policyFacts);
  return multipleRemovalAction(subject, slot, values, projection, reference, policyFacts);
}

function removableValueActions(subject, slot, values, projection, policyFacts) {
  const action = removableValueAction(subject, slot, values, projection, policyFacts);
  if (!action) return Object.freeze([]);
  const reference = slot.valueType === POLICY.referenceValueType;
  const title = reference ? POLICY.referenceTitle : POLICY.ordinaryTitle;
  const suffix = action.prompt?.editorKind === POLICY.editorKind ? "..." : "";
  return Object.freeze([{
    kind: POLICY.actionRowKind, text: `${title} ${slot.predicate}${suffix}`,
    action, semanticColorRole: POLICY.actionRowColor,
  }]);
}

function singleRemovalAction(subject, slot, value, reference, policyFacts) {
  const options = {
    policyFacts,
    title: `${reference ? POLICY.referenceTitle : POLICY.ordinaryTitle} ${slot.predicate}`,
    subject, predicate: slot.predicate,
    valueType: typeof slot.valueType === "string" && slot.valueType ? slot.valueType : POLICY.fallbackValueType,
    value,
  };
  return reference ? buildDetachRelationAction(options) : buildRemoveFactAction(options);
}

function multipleRemovalAction(subject, slot, values, projection, reference, policyFacts) {
  const choiceDetails = removalChoiceDetails(values, projection);
  const title = reference ? POLICY.referenceTitle : POLICY.ordinaryTitle;
  const verb = reference ? POLICY.referenceVerb : POLICY.ordinaryVerb;
  const valueType = typeof slot.valueType === "string" && slot.valueType ? slot.valueType : POLICY.fallbackValueType;
  return buildSemanticMutationAction({
    policyFacts,
    title: `${title} ${slot.predicate}`, operation: reference ? POLICY.referenceOperation : POLICY.ordinaryOperation,
    subject, predicate: slot.predicate, valueType,
    prompt: {
      message: `Choose ${slot.predicate} value to ${verb} from ${subject}`,
      defaultValue: choiceDetails[0].value, allowBlank: false, answerField: POLICY.answerField,
      editorKind: POLICY.editorKind, stage: POLICY.stage, choices: choiceDetails.map(choice => choice.value),
      choiceDetails, valueType,
    },
  });
}

function slotMutationAction(prog, projection, interfaces, context, subject, slot, record, typedRecord, options, helpers) {
  const mode = slotActionMode(slot, record, options.mode);
  const copy = slotEditorCopy(slot, mode);
  const resolved = buildEditableSlotPrompt(prog, projection, interfaces, {
    subject, predicate: slot.predicate, record, typedRecord, currentContext: context, mode,
    choiceDetailsProviders: options.choiceDetailsProviders, contractPolicyProviders: options.contractPolicyProviders,
  }, helpers);
  return buildSemanticMutationAction({
    policyFacts: prog?.facts || prog,
    title: `${copy.title} ${firstText([resolved?.fieldLabel, slot.predicate])}`,
    operation: mode === POLICY.addMode ? POLICY.addOperation : POLICY.setOperation,
    subject, predicate: slot.predicate,
    valueType: firstText([resolved?.valueType, slot.valueType, POLICY.fallbackValueType]),
    prompt: resolved === null ? intrinsicSlotPrompt(slot, subject, record, typedRecord, mode) : resolved,
  });
}

function normalizeRestoreRequest(mutation, helpers) {
  const descriptor = Object(mutation.restoreDeletedCluster);
  const explicit = [
    [Array.isArray(descriptor.restoredSubjects), "restoreDeletedCluster restoredSubjects must be an explicit array."],
    [Array.isArray(descriptor.authorityTargets), "restoreDeletedCluster authorityTargets must be an explicit array."],
  ].find(entry => !entry[0]);
  if (explicit) reject(helpers, explicit[1]);
  const tupleFacts = normalizeRestoreFacts(mutation, helpers);
  const restoredSubjects = uniqueRefList(tupleFacts.map(fact => fact.s));
  if (!restoredSubjects.length) reject(helpers, "restoreDeletedCluster must recreate at least one deleted subject.");
  const descriptorSubjects = uniqueRefList(descriptor.restoredSubjects);
  if (!sameReferenceSet(restoredSubjects, descriptorSubjects)) reject(
    helpers, "restoreDeletedCluster restoredSubjects must match the recreated subject ids.",
    { restoredSubjects, descriptorRestoredSubjects: descriptorSubjects },
  );
  const authorityTargets = uniqueRefList(descriptor.authorityTargets);
  if (!authorityTargets.length) reject(helpers, "restoreDeletedCluster requires at least one authority target anchor.");
  return { descriptor, tupleFacts, restoredSubjects, authorityTargets };
}

function restoreSubjectInterface(tupleFacts, subject, interfaces, helpers) {
  const types = uniqueRefList(tupleFacts.filter(fact => fact.s === subject && fact.p === RESTORE_POLICY.typePredicate).map(fact => fact.o));
  const matches = types.filter(type => interfaces.has(type));
  if (matches.length > 1) helpers.failSemantic(helpers.mutationIssue(
    "ambiguous-interface", `Subject matches multiple schema interfaces: ${matches.join(", ")}.`, { subject },
  ), { statusCode: 400 });
  return matches.length ? interfaces.get(matches[0]) : null;
}
